from zkregion import (
    pedersen_commit, prove_range, prove_region,
    RangeBatchEntry, RegionBatchEntry, Region, RegionProof,
    BoundRangeBatch, BoundRegionBatch,
    prove_range_batch_bound, prove_region_batch_bound,
    verify_range_bound, verify_region_bound,
    merkle_root, prove_multi_inclusion,
)

SMALL = 2**31 - 1
G, H = 3, 5

def cr():
    state = {"v": 1}
    def r(upper):
        state["v"] = (state["v"] * 1103515245 + 12345) % upper
        return state["v"]
    return r

def rentry(value=5, context=b"ctx", blinding=1234):
    c, r = pedersen_commit(value, 0, 10, blinding=blinding, prime=SMALL, generator=G, h=H)
    p = prove_range(c, value, r, context, randbelow=cr())
    return RangeBatchEntry(c, p, context)

def gentry(x=2, y=3, context=b"r", bx=111, by=222):
    region = Region(0, 10, 0, 10)
    cx, rx = pedersen_commit(x, 0, 10, blinding=bx, prime=SMALL, generator=G, h=H)
    cy, ry = pedersen_commit(y, 0, 10, blinding=by, prime=SMALL, generator=G, h=H)
    p = prove_region(cx, cy, x, y, rx, ry, region, context, randbelow=cr())
    return RegionBatchEntry(cx, cy, region, p, context)

from zkregion import _bound_range_leaf, _bound_region_leaf

